function u(n,e){let t=new Date(new Date(n).getTime()-18e5),r=new Date(new Date(e).getTime()+15*6e4);return{openAt:t,closeAt:r}}function o(n,e){let{openAt:t,closeAt:r}=u(n,e),i=new Date;return i>=t&&i<=r}function a(n){if(!n)return null;if(n.joinUrl)return n.joinUrl;if(!n.roomCode)return null;if(String(n.roomCode).startsWith("http"))return n.roomCode;let e=n.token?`?token=${encodeURIComponent(n.token)}`:"";return`https://meet.jit.si/${n.roomCode}${e}`}function s(n,e){if(!n||!e)return 0;let t=Math.max(0,new Date(e).getTime()-new Date(n).getTime());return Math.round(t/(1e3*60*60)*100)/100}function c(n){return n===1?"1 hour":`${n} hours`}function d(n){return"$"+(Number(n??0)||0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}function l(n){switch(n){case 0:return"Pending";case 1:return"Paid";case 2:return"Failed";case 3:return"Refunded";case 4:return"Expired";default:return""}}function f(n){switch(n){case 0:return"Card (Stripe)";case 1:return"Bank Transfer";default:return""}}export{u as a,o as b,a as c,s as d,c as e,d as f,l as g,f as h};
